/* Focused, offline XLSX reader: values, shared strings, dates, workbook relationships. */
(function(root){'use strict';
const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('Virheellinen Excel XML');return d;};
const all=(d,n)=>Array.from(d.getElementsByTagNameNS('*',n));
const content=(d,n)=>all(d,n).map(x=>x.textContent).join('');
async function readXLSX(buffer){if(buffer.byteLength>25*1024*1024)throw Error('Tiedoston enimmäiskoko on 25 Mt. Jaa pääkirja pienempiin osiin.');const zip=await JSZip.loadAsync(buffer);let expanded=0;const get=async path=>{const f=zip.file(path);if(!f)throw Error('Excelistä puuttuu '+path);const v=await f.async('string');expanded+=v.length;if(expanded>100*1024*1024)throw Error('Excelin purettu sisältö on liian suuri');return xml(v);};const wb=await get('xl/workbook.xml'),rels=await get('xl/_rels/workbook.xml.rels');const paths=new Map(all(rels,'Relationship').map(r=>[r.getAttribute('Id'),r.getAttribute('Target')]));let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=all(await get('xl/sharedStrings.xml'),'si').map(s=>content(s,'t'));
 let dateStyles=new Set();if(zip.file('xl/styles.xml')){const s=await get('xl/styles.xml');const formats=new Map(all(s,'numFmt').map(f=>[Number(f.getAttribute('numFmtId')),f.getAttribute('formatCode')]));const xfs=all(s,'cellXfs')[0];if(xfs)all(xfs,'xf').forEach((x,i)=>{const n=Number(x.getAttribute('numFmtId')),fmt=(formats.get(n)||'').replace(/"[^"]*"|\[[^\]]*\]/g,'');if((n>=14&&n<=22)||(n>=45&&n<=47)||(/[dy]/i.test(fmt)))dateStyles.add(i);});}
 const is1904=all(wb,'workbookPr').some(x=>['1','true'].includes(x.getAttribute('date1904')));const sheets=[];
 for(const sheet of all(wb,'sheet')){let id=sheet.getAttribute('r:id')||sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');let path=paths.get(id);if(!path)throw Error('Välilehden viittaus puuttuu');path=path.startsWith('/')?path.slice(1):'xl/'+path;const parts=[];for(const x of path.split('/')){if(x==='..')parts.pop();else if(x!=='.')parts.push(x);}path=parts.join('/');const doc=await get(path),grid=[];for(const row of all(doc,'row')){const ri=Number(row.getAttribute('r'))-1;if(ri<0||ri>200000)throw Error('Liian suuri tai virheellinen rivinumero');const a=[];for(const c of all(row,'c')){const ref=c.getAttribute('r')||'',letters=ref.match(/^[A-Z]+/)?.[0]||'A';let ci=0;for(const x of letters)ci=ci*26+x.charCodeAt(0)-64;ci--;if(ci>500)throw Error('Liian monta saraketta');const type=c.getAttribute('t'),v=all(c,'v')[0]?.textContent;let value=v??'';if(type==='s')value=strings[Number(v)]??'';else if(type==='inlineStr')value=content(c,'t');else if(type==='e')throw Error('Excelin virhearvo solussa '+ref);else if(v!==undefined&&type!=='str'&&type!=='d'){value=Number(v);if(dateStyles.has(Number(c.getAttribute('s')||0))&&Number.isFinite(value))value=new Date(Date.UTC(is1904?1904:1899,is1904?0:11,is1904?1:30)+Math.floor(value)*86400000).toISOString().slice(0,10);}if(all(c,'f').length&&v===undefined)throw Error('Kaavan laskettu arvo puuttuu solusta '+ref+'. Tallenna Excel uudelleen.');a[ci]=value;}grid[ri]=a;}sheets.push({name:sheet.getAttribute('name'),grid});}return sheets;
}root.readXLSX=readXLSX;})(typeof window==='undefined'?globalThis:window);
